import json,re,os
def load():
    d=os.path.normpath(os.environ['RLM_SESSION_DIR'])
    t=open(d+'/../../sessions/'+os.path.basename(d)+'.jsonl').read().replace('\\n','\n'); G={}
    for m in re.finditer(r'(Demo pair \d+ (?:input|output)|Test input) \((\d+)x(\d+)\):\n',t):
        k,h,w=m[1],int(m[2]),int(m[3])
        rows=[r.split() for r in t[m.end():].split('\n')[:h]]
        if k not in G and all(len(r)==w and all(x.isdigit() for x in r) for r in rows):
            G[k]=[[int(x) for x in r] for r in rows]
    return G
G=load()
for p in (1,2):
    gi,go=G[f'Demo pair {p} input'],G[f'Demo pair {p} output']
    bg=gi[0][0]; H=len(gi); W=len(gi[0])
    dr=[i for i,row in enumerate(gi) if len(set(row))==1 and row[0]!=bg]
    dc=[j for j in range(W) if len({row[j] for row in gi})==1 and gi[0][j]!=bg]
    # block boundaries
    rb=[-1]+dr+[H]; cb=[-1]+dc+[W]
    from collections import Counter
    cnt={}
    minority=Counter(v for row in gi for v in row).most_common()[-1][0]
    for a in range(len(rb)-1):
        for b in range(len(cb)-1):
            c=sum(1 for i in range(rb[a]+1,rb[a+1]) for j in range(cb[b]+1,cb[b+1]) if gi[i][j]==minority)
            cnt[(a,b)]=c
    print(p,'minority',minority,'bg',bg)
    for a in range(len(rb)-1):
        print([cnt[(a,b)] for b in range(len(cb)-1)],'  out:',go[a])

